INSERT INTO whatsapp_group_member_snapshot (
  group_link_id, group_jid, participant_jid, phone, role, is_admin, is_owner,
  snapshot_at, created_at, updated_at
) VALUES

  (
    #{row.groupLinkId}, #{row.groupJid}, #{row.participantJid}, #{row.phone}, #{row.role},
    CASE WHEN #{row.isOwner} = TRUE THEN 1 ELSE COALESCE(#{row.isAdmin}, FALSE) END,
    COALESCE(#{row.isOwner}, FALSE), #{row.snapshotAt}, #{row.createdAt}, #{row.updatedAt}
  )
